R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p
mkdir -p $R/sb_ktfix/prompts $R/sb_ktfix/out; echo  | base64 -d > $R/sb_ktfix/prompts/sb_ktfix.md
{ echo sb_ktfix; cat $R/sb_queue/queue.txt; } > $R/sb_queue/q.tmp; cat $R/sb_queue/q.tmp > $R/sb_queue/queue.txt; echo Q: $(cat $R/sb_queue/queue.txt | tr "\n" " ")
mkdir -p $R/sb_rlrev3; cp $R/sb_cursor_probe/AGENTS.md $R/sb_rlrev3/AGENTS.md; echo  | base64 -d > $R/sb_rlrev3/PROMPT.md
cd $R/sb_rlrev3 && tmux new-session -d -s sb_rlrev3 "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 5400 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo; wc -c $R/sb_mfrev/cursor.log
